{
    private readonly EnemyAI owner;
    public ChaseState(EnemyAI owner) => this.owner = owner;

    public void Enter() => owner.PlayAnimation("Run");
    public void Tick()  => owner.MoveToward(owner.TargetPosition);
    public void Exit()  => owner.StopMoving();
}

